$ErrorActionPreference = 'Stop'
$outDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$htmlPath = Join-Path $outDir 'NetMind_Role_Based_System_Study_Guide_source.html'
$pdfPath = Join-Path $outDir 'NetMind_Role_Based_System_Study_Guide.pdf'
$roles = @(
 @{name='John Arvie Capulo';role='Project Manager';pages=10;focus='scope, delivery, risks, stakeholder communication, approvals, and release readiness';topics=@('Project charter and success measures','Stakeholder map and role boundaries','End-to-end system map','Release planning and work breakdown','Requirements traceability','Risk register and mitigation','Access and data quality governance','Training and attendance workflow oversight','Match, wellness, and injury workflow oversight','Handover and retrospective')},
 @{name='Vincent Torres';role='Programmer';pages=20;focus='implementation, debugging, integration, security, and deployment of the application';topics=@('Repository orientation and startup','Web frontend routing','Mobile application structure','API request conventions','Express application pipeline','JWT authentication','Authorization rules','Database schema','Generic CRUD resources','Team and roster implementation','Trainer assignment implementation','Drills and training assignments','Drill performance logs','Performance logs and summaries','Wellness and injury features','Schedules, QR, and attendance','Matches, lineups, and scores','Rankings and analytics','Files, notifications, and email','Testing and deployment')},
 @{name='Ervin Augis';role='Tester';pages=10;focus='functional, permission, reliability, data-integrity, and release testing';topics=@('Test strategy and system inventory','Test data and environments','Registration and login tests','Session and authorization tests','Team and roster tests','Training and performance tests','Attendance and QR tests','Match, lineup, and ranking tests','Wellness, injury, and notification tests','Regression report and defect handover')},
 @{name='Althea Adobas';role='Documentary';pages=10;focus='accurate user, technical, operational, and presentation documentation';topics=@('Documentation plan and audience','System overview and glossary','Architecture narrative','Roles and permissions guide','Account lifecycle guide','Team and training guide','Performance and analytics guide','Match, attendance, wellness, and injury guide','API, data, configuration, and operations reference','Review, versioning, and final package')},
 @{name='Mae Kyla Olita';role='System Analyst';pages=10;focus='requirements, use cases, rules, data definitions, and acceptance criteria';topics=@('Problem and scope','Actors and use cases','Context and boundary analysis','Permission matrix','Data model','Authentication requirements','Team and training requirements','Performance, wellness, and attendance requirements','Match, ranking, and analytics requirements','Traceability and acceptance criteria')},
 @{name='Rea Batiao';role='System Analyst';pages=10;focus='workflows, integrations, exceptions, measurable rules, and change impact analysis';topics=@('Current-to-future workflow','Flow notation and system boundary','Account and authorization analysis','Profile and media process','Team and trainer lifecycle','Training and drill-log process','Performance and summary process','Wellness, injury, QR, and attendance process','Match, ranking, and notification process','Data integrity, exceptions, and change impact')}
)
$facts=@('NetMind is a volleyball analytics and team-management system. It keeps users, teams, memberships, trainer assignments, seasons, matches, drills, training assignments, performance logs, wellness check-ins, attendance, injuries, lineups, rankings, comparisons, notifications, and push subscriptions.','The system has a React/Vite web client, an Expo mobile client, and a Node.js/Express API. The web client contains coach and trainer dashboards; the mobile client includes dashboard, activity, attendance, performance, training, wellness, injury, notifications, profile, and settings views.','The API uses a protected /api area. After a Bearer JWT is validated, authorization checks determine whether the authenticated coach, trainer, or player can access the requested team, player, match, or record. Interface visibility is not a substitute for server authorization.','Authentication validates inputs, hashes passwords with bcrypt, signs JWT tokens, rate-limits registration and login, and rechecks the active user account when a token is used. This protects account access and blocks deactivated users.','Database relationships and constraints protect integrity: user roles and volleyball positions are restricted, team membership is unique, check-ins are unique per player and date, attendance statuses are controlled, and records use foreign keys to connect a player, staff member, team, season, or match.','A player summary combines performance actions, wellness indicators, check-ins, training completion, drill results, and active injuries. A team dashboard combines team information, match record, attendance, and rankings. These summaries support decisions but remain dependent on accurate inputs.','Training flows begin with a drill or assigned focus, target values, and a due date. Players and staff record status and drill-performance information. The records then support follow-up, completion tracking, and performance analysis.','Attendance can be recorded in bulk and is tied to team, player, session type, date, status, staff marker, and optional late minutes or reason. Training schedules and QR tokens support controlled check-in; token expiry and authorization are important exception cases.','Match flows include a team, opponent, date, match type, season, scores, outcome, and optional per-match scoring. A finalized result can recalculate season ranking fields such as wins, losses, win percentage, points for, points against, and point difference.','Sensitive personal and sports-health data must be handled with least privilege. Environment secrets, passwords, API keys, email settings, and Drive credentials must never appear in public documentation, screenshots, commits, test reports, or presentation slides.')
function E([string]$v){[System.Net.WebUtility]::HtmlEncode($v)}
$b=[Text.StringBuilder]::new();[void]$b.AppendLine('<!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:1.45cm}body{font-family:Arial;color:#18222d;font-size:10.4pt;line-height:1.37}.page{page-break-after:always;min-height:25cm}h1{font-size:25pt;color:#0b5b85;margin:0 0 4px}h2{font-size:16pt;color:#0b5b85;margin:5px 0 14px}h3{font-size:11.5pt;color:#0b5b85;margin:15px 0 5px}.meta{color:#5b6770;margin-bottom:15px}.box{background:#eef7fb;border-left:4px solid #0b5b85;padding:10px;margin:10px 0}li{margin:5px 0}.foot{margin-top:16px;color:#5b6770;font-size:8.5pt}</style></head><body>')
foreach($r in $roles){for($i=0;$i -lt $r.pages;$i++){$topic=$r.topics[$i];$fact=$facts[$i%$facts.Count];$support=$facts[($i+4)%$facts.Count];[void]$b.AppendLine("<section class='page'><h1>NetMind Study Guide</h1><div class='meta'><b>Assigned to:</b> $(E $r.name) | <b>Role:</b> $(E $r.role) | Page $($i+1) of $($r.pages)</div><h2>$(E $topic)</h2><div class='box'><b>Role objective.</b> Study this topic to prepare for the capstone presentation. As the $(E $r.role), $(E $r.name) should be ready to explain how this part of NetMind supports $($r.focus).</div><h3>System knowledge</h3><p>$(E $fact)</p><p>$(E $support)</p><h3>Flow to explain during the presentation</h3><ol><li>State the business trigger and the actor who starts the process.</li><li>Identify the client screen or mobile action and the API request it requires.</li><li>Explain validation, authentication, and role or ownership authorization before a write occurs.</li><li>Name the database record or relationship that is created, updated, read, calculated, or protected.</li><li>Describe the visible result: dashboard update, status, summary, ranking, notification, or clear error.</li></ol><h3>Responsibilities for this role</h3><p>A $($r.role) must make this flow understandable, reliable, and verifiable within the team. Capture the purpose, actors, inputs, preconditions, expected result, exception cases, and evidence. Confirm behavior against the web or mobile screen, backend route, data schema, and available tests rather than relying only on a design assumption.</p><h3>Study questions</h3><ul><li>Which user role is allowed to start, review, or change this information?</li><li>What data proves that the action happened, and which dashboard or summary uses it?</li><li>What invalid input, missing relationship, expired session, or unauthorized request must be handled?</li><li>How would the team demonstrate that the workflow protects accuracy, privacy, and accountability?</li></ul><h3>Presentation checkpoint</h3><p>Prepare a short explanation in this order: <b>need - actor - action - validation - protected data update - result - benefit</b>. Use an example from volleyball operations, such as assigning a drill, logging attendance, recording match performance, reviewing wellness, or finalizing a ranking. Mention the exception path as well as the successful path.</p><div class='foot'>NetMind Role-Based System Study Guide | Generated from the current project structure and implementation patterns</div></section>")}}
[void]$b.AppendLine('</body></html>');[IO.File]::WriteAllText($htmlPath,$b.ToString(),[Text.UTF8Encoding]::new($false))
$word=New-Object -ComObject Word.Application;$word.Visible=$false;$doc=$null
try{$doc=$word.Documents.Open($htmlPath);$doc.ExportAsFixedFormat($pdfPath,17);Write-Output "Created PDF: $pdfPath"}finally{if($doc){$doc.Close(0)};if($word){$word.Quit()}}
